        for (const auto& edge : (*this).nodes[static_cast<std::size_t>(owner)].edges) {
            if ((edge.role == EdgeRole::Specifiers)) {
                const std::string name = (importing ? (*this).get(edge.node, AttributeKind::Local) : (*this).get(edge.node, AttributeKind::Alias));
                const std::string effective = ((name == std::string("")) ? (*this).get(edge.node, AttributeKind::Name) : name);
                if (ets_includes_vec<std::string>(names, effective)) {
                    (*this).reportAt((*this).node(edge.node).start, std::string("Nombre duplicado en la lista de import/export"));
                }
                ets_push_vec<std::string>(names, effective);
            }
        }
