struct ModuleLoader {
    LoaderOptions options;
    SyntaxCache cache;

    ModuleLoader& constructor(LoaderOptions options) {
        ((*this).options = options);
        ((*this).cache = SyntaxCache{}.constructor(options.cacheDirectory, options.syntaxKey));
        return *this;
}

    ModuleGraph load(std::string entry) {
        SyntaxCache cache = (*this).cache;
        cache.resetStats();
        const std::string canonical = resolveSourceFile(normalizePath(entry));
        ModuleGraph graph = ModuleGraph{}.constructor(canonical);
        if ((canonical == std::string(""))) {
            ets_push_vec<SourceDiagnostic>(graph.diagnostics, SourceDiagnostic{}.constructor(std::string("loader"), ets::concat(std::string("No se puede resolver el módulo '"), entry, std::string("' (se probaron .ts y .ets)")), normalizePath(entry), originToken()));
            (graph.success = false);
            ((*this).cache = cache);
            return graph;
        }
        if ((*this).options.verbose) {
            printError(ets::concat(std::string("frontend: reading/parsing "), canonical));
        }
        std::vector<LoadedFile> discovered = std::vector<LoadedFile>{readModule(canonical, graph, cache)};
        std::vector<double> stack = std::vector<double>{0.0};
        while ((stack.size() > 0.0)) {
            const double ets_local_index = stack[static_cast<std::size_t>((stack.size() - 1.0))];
            LoadedFile module = discovered[static_cast<std::size_t>(ets_local_index)];
            if ((module.cursor >= module.requests.size())) {
                (module.state = 2.0);
                ets_set_vec<LoadedFile>(discovered, ets_local_index, module);
                (module.cached.record.dependencies = module.dependencies);
                cache.save(module.cached.record);
                ets_push_vec<LoadedFile>(graph.modules, module);
                ets_pop_vec<double>(stack);
            } else {
                ModuleRequest request = module.requests[static_cast<std::size_t>(module.cursor)];
                (module.cursor = (module.cursor + 1.0));
                const std::string dependency = resolveRequest(module.file, request.specifier, (*this).options);
                const ParserToken token = module.cached.result.ast.nodes[static_cast<std::size_t>(request.node)].start;
                ets_set_vec<LoadedFile>(discovered, ets_local_index, module);
                if ((dependency == std::string(""))) {
                    ets_push_vec<SourceDiagnostic>(graph.diagnostics, SourceDiagnostic{}.constructor(std::string("resolver"), ets::concat(std::string("No se puede resolver el import '"), request.specifier, std::string("' desde "), module.file), module.file, token));
                } else {
                    (request.dependency = dependency);
                    ets_set_vec<ModuleRequest>(module.requests, (module.cursor - 1.0), request);
                    if ((!ets_includes_vec<std::string>(module.dependencies, dependency))) {
                        ets_push_vec<std::string>(module.dependencies, dependency);
                    }
                    ets_set_vec<LoadedFile>(discovered, ets_local_index, module);
                    double existing = (-1.0);
                    for (double i = 0.0; (i < discovered.size()); (i = (i + 1.0))) {
                        if ((discovered[static_cast<std::size_t>(i)].file == dependency)) {
                            (existing = i);
                            break;
                        }
                    }
                    if ((existing < 0.0)) {
                        if ((*this).options.verbose) {
                            printError(ets::concat(std::string("frontend: reading/parsing "), dependency));
                        }
                        ets_push_vec<LoadedFile>(discovered, readModule(dependency, graph, cache));
                        ets_push_vec<double>(stack, (discovered.size() - 1.0));
                    } else {
                        if ((discovered[static_cast<std::size_t>(existing)].state == 1.0)) {
                            std::vector<std::string> cycle = std::vector<std::string>();
                            bool started = false;
                            for (const auto& active : stack) {
                                if ((active == existing)) {
                                    (started = true);
                                }
                                if (started) {
                                    ets_push_vec<std::string>(cycle, discovered[static_cast<std::size_t>(active)].file);
                                }
                            }
                            ets_push_vec<std::string>(cycle, dependency);
                            ets_push_vec<SourceDiagnostic>(graph.diagnostics, SourceDiagnostic{}.constructor(std::string("resolver"), ets::concat(std::string("Ciclo de imports: "), ets_join_vec(cycle, std::string(" -> "))), module.file, token));
                        }
                    }
                }
            }
        }
        (graph.hits = cache.hits);
        (graph.misses = cache.misses);
        (graph.writes = cache.writes);
        (graph.success = (graph.diagnostics.size() == 0.0));
        ((*this).cache = cache);
        return graph;
    }

    void default_constructor() {
        (*this).options = LoaderOptions{};
        (*this).cache = SyntaxCache{};
    }
};

