struct IrBorrowAnalysis {
    std::vector<std::string> typeNames;
    IrFunction body;
    std::vector<IrLeaseSet> values;
    std::vector<IrLeaseSet> places;
    std::vector<IrLeaseSet> liveIn;
    std::vector<IrLeaseSet> liveOut;

    IrBorrowAnalysis& constructor(IrFunction input, std::vector<std::string> typeNames) {
        ((*this).typeNames = typeNames);
        ((*this).body = input);
        ((*this).values = std::vector<IrLeaseSet>());
        ((*this).places = std::vector<IrLeaseSet>());
        ((*this).liveIn = std::vector<IrLeaseSet>());
        ((*this).liveOut = std::vector<IrLeaseSet>());
        for (const auto& v : input.values) {
            ets_push_vec<IrLeaseSet>((*this).values, IrLeaseSet{}.constructor());
        }
        for (const auto& p : input.places) {
            ets_push_vec<IrLeaseSet>((*this).places, IrLeaseSet{}.constructor());
        }
        for (const auto& b : input.blocks) {
            ets_push_vec<IrLeaseSet>((*this).liveIn, IrLeaseSet{}.constructor());
            ets_push_vec<IrLeaseSet>((*this).liveOut, IrLeaseSet{}.constructor());
        }
        return *this;
}

    std::vector<double> placeUses(double place) const {
        std::vector<double> result = std::vector<double>();
        double count = 0.0;
        while ((((place >= 0.0) && (place < (*this).body.places.size())) && (count < (*this).body.places.size()))) {
            (result = irLeaseUnion(result, (*this).places[static_cast<std::size_t>(place)].values));
            (place = (*this).body.places[static_cast<std::size_t>(place)].base);
            (count = (count + 1.0));
        }
        return result;
    }

    std::vector<double> uses(IrInstruction i) const {
        std::vector<double> result = std::vector<double>();
        for (const auto& operand : i.operands) {
            if (((operand >= 0.0) && (operand < (*this).values.size()))) {
                (result = irLeaseUnion(result, (*this).values[static_cast<std::size_t>(operand)].values));
            }
        }
        if ((i.place >= 0.0)) {
            (result = irLeaseUnion(result, (*this).placeUses(i.place)));
        }
        return result;
    }

    void propagate() {
        for (double lease = 0.0; (lease < (*this).body.leases.size()); (lease = (lease + 1.0))) {
            if ((((*this).body.leases[static_cast<std::size_t>(lease)].value >= 0.0) && ((*this).body.leases[static_cast<std::size_t>(lease)].value < (*this).values.size()))) {
                ets_push_vec<double>((*this).values[static_cast<std::size_t>((*this).body.leases[static_cast<std::size_t>(lease)].value)].values, lease);
            }
        }
        bool changed = true;
        while (changed) {
            (changed = false);
            for (const auto& block : (*this).body.blocks) {
                for (const auto& i : block.instructions) {
                    std::vector<double> values = std::vector<double>();
                    if ((ets_includes_vec<std::string>(std::vector<std::string>{std::string("load"), std::string("move")}, i.op) && (i.place >= 0.0))) {
                        (values = (*this).placeUses(i.place));
                    }
                    if (ets_includes_vec<std::string>(std::vector<std::string>{std::string("convert"), std::string("closure"), std::string("aggregate"), std::string("record"), std::string("own")}, i.op)) {
                        for (const auto& operand : i.operands) {
                            if (((operand >= 0.0) && (operand < (*this).values.size()))) {
                                (values = irLeaseUnion(values, (*this).values[static_cast<std::size_t>(operand)].values));
                            }
                        }
                    }
                    if (((((i.op == std::string("store")) && (i.place >= 0.0)) && (i.operands.size() == 1.0)) && (i.operands[static_cast<std::size_t>(0.0)] >= 0.0))) {
                        const std::vector<double> next = irLeaseUnion((*this).places[static_cast<std::size_t>(i.place)].values, (*this).values[static_cast<std::size_t>(i.operands[static_cast<std::size_t>(0.0)])].values);
                        if ((!irLeaseEqual(next, (*this).places[static_cast<std::size_t>(i.place)].values))) {
                            ((*this).places[static_cast<std::size_t>(i.place)].values = next);
                            (changed = true);
                        }
                    }
                    if ((((i.result >= 0.0) && (i.result < (*this).values.size())) && (!primitiveType((*this).typeNames[static_cast<std::size_t>((*this).body.values[static_cast<std::size_t>(i.result)])])))) {
                        const std::vector<double> next = irLeaseUnion((*this).values[static_cast<std::size_t>(i.result)].values, values);
                        if ((!irLeaseEqual(next, (*this).values[static_cast<std::size_t>(i.result)].values))) {
                            ((*this).values[static_cast<std::size_t>(i.result)].values = next);
                            (changed = true);
                        }
                    }
                }
            }
        }
    }

    void liveness() {
        bool changed = true;
        while (changed) {
            (changed = false);
            for (double b = ((*this).body.blocks.size() - 1.0); (b >= 0.0); (b = (b - 1.0))) {
                std::vector<double> outgoing = std::vector<double>();
                for (const auto& target : (*this).body.blocks[static_cast<std::size_t>(b)].targets) {
                    (outgoing = irLeaseUnion(outgoing, (*this).liveIn[static_cast<std::size_t>(target)].values));
                }
                std::vector<double> live = outgoing;
                if (((*this).body.blocks[static_cast<std::size_t>(b)].value >= 0.0)) {
                    (live = irLeaseUnion(live, (*this).values[static_cast<std::size_t>((*this).body.blocks[static_cast<std::size_t>(b)].value)].values));
                }
                for (double at = ((*this).body.blocks[static_cast<std::size_t>(b)].instructions.size() - 1.0); (at >= 0.0); (at = (at - 1.0))) {
                    const auto i = (*this).body.blocks[static_cast<std::size_t>(b)].instructions[static_cast<std::size_t>(at)];
                    if (((i.lease >= 0.0) && ((i.op == std::string("borrow")) || (i.op == std::string("address"))))) {
                        (live = irLeaseRemove(live, i.lease));
                    }
                    (live = irLeaseUnion(live, (*this).uses(i)));
                }
                if (((!irLeaseEqual(live, (*this).liveIn[static_cast<std::size_t>(b)].values)) || (!irLeaseEqual(outgoing, (*this).liveOut[static_cast<std::size_t>(b)].values)))) {
                    ((*this).liveIn[static_cast<std::size_t>(b)].values = live);
                    ((*this).liveOut[static_cast<std::size_t>(b)].values = outgoing);
                    (changed = true);
                }
            }
        }
    }

    void default_constructor() {
        (*this).typeNames = std::vector<std::string>{};
        (*this).body = IrFunction{};
        (*this).values = std::vector<IrLeaseSet>{};
        (*this).places = std::vector<IrLeaseSet>{};
        (*this).liveIn = std::vector<IrLeaseSet>{};
        (*this).liveOut = std::vector<IrLeaseSet>{};
    }
};

